-- =============================================-- Author:		<Jose Roman>-- Create date: <13-07-2018>-- Description:	<Se consulta la cantidad de materiales que hicieron falta de recibir al momento de cerrar el pedido>-- =============================================create procedure MM_SP_ConsultaValidacionReaperturaPedido --1632	@IdPedido INT,	/*--------------------parametros contrato  --------------------*/    @IdContrato    INT = null,    @IdUsuario     INT = null,    @FechaRegistro DATETIME = null	/*-------------------------------------------------------------*/ASBEGIN	SELECT 		pod.IdSolicitudPedidoDetalle,		(pd.Cantidad - SUM(ISNULL(apd.Cantidad, 0))) AS CantidadFaltanteAlCierre,		pd.IdPedidoDetalle	FROM dbo.MM_Pedido p	INNER JOIN dbo.MM_PedidoDetalle pd ON pd.IdPedido = p.IdPedido	LEFT JOIN dbo.MM_AceptacionPedidoDetalle apd ON apd.IdPedidoDetalle = pd.IdPedidoDetalle	INNER JOIN dbo.MM_PeticionOfertaDetalle pod ON pod.IdPeticionOfertaDetalle = pd.IdPeticionOfertaDetalle	WHERE p.idpedido = @IdPedido		AND ISNULL(apd.IdEstatusEliminado, 0) = 0	GROUP BY pd.IdPedidoDetalle, apd.Cantidad, pd.Cantidad, pod.IdSolicitudPedidoDetalleEND